<?php if(can($pdo,$user,'leave.create')):?><div class="balance-actions"><button type="button" class="button primary" data-open-dialog="leave-request-dialog">+ Create leave request</button></div><dialog id="leave-request-dialog" class="attendance-dialog balance-dialog" aria-labelledby="leave-request-title" <?=($error&&($_POST['action']??'')==='core_leave')?'data-auto-open':''?>><div class="card-heading"><div><h2 id="leave-request-title">Create leave request</h2><p class="hint">Select an employee, leave type and dates.</p></div><button type="button" class="button small" data-close-dialog aria-label="Close leave request form">Close</button></div><?php if($error&&($_POST['action']??'')==='core_leave'):?><p class="alert error" role="alert"><?=h($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data" class="form-grid core-form"><?php ftoken();chr_hidden('action','core_leave');$v=$error?$_POST:[];chr_select('employee_id','Employee',$v['employee_id']??'', [''=>'Select employee']+$employeeOptions);$activeTypes=[];foreach(chr_rows($pdo,'leave_policy') as $p)if($p['status']==='Published')$activeTypes[$p['values']['type']]=$p['title'];chr_select('category','Leave type',$v['category']??'', [''=>'Select type']+$activeTypes);field('start_date','From',$v,'date',true);field('end_date','To',$v,'date',true);choose('day_part','Day period',$v,['Full Day','First Half','Second Half']);field('subject','Subject',$v,'text',true,180);?><label class="full">Reason<textarea name="details" maxlength="5000" required><?=h($v['details']??'')?></textarea></label><label>Optional attachment<input type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png"></label><p class="full">Published holidays and assigned weekly offs are excluded. Half-day requests cover one date and count as 0.5 day. Without an assigned shift, no weekly off is assumed. Requests become effective only after approval.</p><div class="full"><button class="button primary">Submit request</button></div></form></dialog><?php endif;?>
