$where=["r.kind='leave'"];$args=[];foreach(['employee_id'=>'r.user_id','department_id'=>'e.department_id','category'=>'r.category','status'=>'r.status'] as $key=>$column)if(!empty($_GET[$key])){$where[]=$column.'=?';$args[]=$_GET[$key];}try{if(!empty($_GET['from'])){$where[]='r.end_date>=?';$args[]=chr_date($_GET['from']);}if(!empty($_GET['to'])){$where[]='r.start_date<=?';$args[]=chr_date($_GET['to']);}}catch(InvalidArgumentException $e){echo '<div class="alert error">'.h($e->getMessage()).'</div>';return;}
if($user['role']!=='super_admin'){$where[]="(r.user_id=? OR EXISTS (SELECT 1 FROM hr_records wf WHERE wf.module='leave_workflow' AND wf.title=CONCAT('Leave #',r.id) AND JSON_CONTAINS(JSON_EXTRACT(wf.data,'$.approvers'),JSON_OBJECT('id',CAST(? AS UNSIGNED)))))";$args[]=$user['id'];$args[]=$user['id'];}
$base=' FROM hr_requests r JOIN users u ON u.id=r.user_id LEFT JOIN employees e ON e.user_id=r.user_id LEFT JOIN users reviewer ON reviewer.id=r.reviewer_id LEFT JOIN hr_leave_details ld ON ld.request_id=r.id WHERE '.implode(' AND ',$where);$q=$pdo->prepare('SELECT COUNT(*)'.$base);$q->execute($args);$count=(int)$q->fetchColumn();$number=max(1,(int)($_GET['p']??1));$offset=($number-1)*30;$q=$pdo->prepare('SELECT r.*,u.name,reviewer.name reviewer_name,ld.days,ld.day_part,ld.attachment_record_id'.$base.' ORDER BY r.id DESC LIMIT 30 OFFSET '.$offset);$q->execute($args);$requests=$q->fetchAll(PDO::FETCH_ASSOC);
?><section class="card"><h2>Submitted leave applications</h2><p>Employee leave applications appear here after submission. Use the status filter to review pending, approved, rejected or cancelled requests.</p><div class="table-scroll"><table class="directory"><thead><tr><th>Employee</th><th>Type / period</th><th>Dates</th><th>Days</th><th>Reason</th><th>Applied</th><th>Status / reviewer</th><th>Actions</th></tr></thead><tbody><?php if(!$requests):?><tr><td colspan="8">No matching requests.</td></tr><?php endif;foreach($requests as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['category'])?><small><?=h($r['day_part']??'Full Day (legacy)')?></small></td><td><?=h($r['start_date'])?> → <?=h($r['end_date'])?></td><td><?=h($r['days']??count(chr_request_days($pdo,$r)))?></td><td><details><summary><?=h($r['subject'])?></summary><p><?=nl2br(h($r['details']))?></p><?php if($r['attachment_record_id']):$f=$pdo->prepare('SELECT id FROM hr_files WHERE record_id=? ORDER BY id DESC LIMIT 1');$f->execute([$r['attachment_record_id']]);$fid=$f->fetchColumn();if($fid):?><a href="document.php?id=<?=(int)$fid?>">Download attachment</a><?php endif;endif;?></details></td><td><?=h($r['created_at'])?></td><td><?php fbadge($r['status'],$r['status']==='Approved');?><small><?=h($r['reviewer_name']??'Awaiting review')?></small></td><td><?php if(($r['status']==='Pending'&&ess_can_review($pdo,$user,$r))||(in_array($r['status'],['Pending','Approved'],true)&&can($pdo,$user,'leave.manage'))):?><form method="post" data-confirm="Save this leave decision?"><?php ftoken();chr_hidden('action','core_review');chr_hidden('id',$r['id']);?><label>Decision reason<input name="decision_reason" maxlength="3000" placeholder="Required for rejection or override"></label><?php if($r['status']==='Pending'&&ess_can_review($pdo,$user,$r)):?><button class="button primary" name="status" value="Approved">Approve</button><button class="button" name="status" value="Rejected">Reject</button><?php endif;if(can($pdo,$user,'leave.manage')):?><button class="button" name="status" value="Cancelled">Cancel</button><?php endif;?></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><nav class="pagination" aria-label="Leave pages"><?php for($i=max(1,$number-2);$i<=min((int)ceil($count/30),$number+2);$i++):?><a class="button" href="?<?=h(http_build_query(array_merge($_GET,['p'=>$i])))?>"><?=$i?></a><?php endfor;?></nav></section><p>Legacy requests retain their original calendar-day accounting. New requests use the stored day breakdown. Cancelling an approved request releases its balance without deleting its history.</p>
